package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.*;import java.io.*;import java.util.*;
/** The window selects destinations and options; the foreground work journal owns the operation. */
final class WorkspaceBackupUi {
 static final int EXPORT=84,RESTORE=85;final Activity a;boolean conversations,audio;
 WorkspaceBackupUi(Activity a){this.a=a;android.content.SharedPreferences p=a.getSharedPreferences("reading_tools",0);conversations=p.getBoolean("backup_conversations",false);audio=p.getBoolean("backup_external_audio",false);}
 void show(){UiPanel panel=new UiPanel(a,"Cópia e recuperação",null,"folder");panel.action("folder","Guardar cópia completa",null,false,this::options);panel.action("restore","Recuperar cópia completa",null,false,()->choose(false));panel.action("clock","Recuperações locais anteriores",null,false,this::recoveries);panel.action("clock","Tarefas em segundo plano",null,false,()->TaskService.open(a));panel.note("Pode continuar a usar o aparelho. O progresso fica guardado em Tarefas.");panel.show();}
 void options(){LinearLayout form=PlusUi.column(a);CheckBox chat=new CheckBox(a),wav=new CheckBox(a);chat.setText(AppLanguage.text(a,"Incluir conversas do assistente"));wav.setText(AppLanguage.text(a,"Incluir WAVs de narração externos"));chat.setTextColor(AppPalette.of(a).ink);wav.setTextColor(AppPalette.of(a).ink);chat.setChecked(conversations);wav.setChecked(audio);form.addView(chat);form.addView(wav);TextView estimate=PlusUi.text(a,"A calcular tamanho…",13);form.addView(estimate);PlusUi.run(a,()->{long bytes=0,books=0;try(StudyStore db=new StudyStore(a);android.database.Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*),COALESCE(SUM(bytes),0) FROM (SELECT path,MAX(bytes) AS bytes FROM materials GROUP BY path)",null)){c.moveToFirst();books=c.getLong(0);bytes=c.getLong(1);}final String summary=books+" "+AppLanguage.text(a,"livros")+" · "+android.text.format.Formatter.formatShortFileSize(a,bytes)+" + "+AppLanguage.text(a,"notas, fundo e opções seleccionadas");PlusUi.post(a,()->estimate.setText(summary));});new UiDialog.Builder(a).setTitle("Conteúdo da cópia").setView(form).setPositiveButton("Escolher destino",(d,w)->{conversations=chat.isChecked();audio=wav.isChecked();a.getSharedPreferences("reading_tools",0).edit().putBoolean("backup_conversations",conversations).putBoolean("backup_external_audio",audio).apply();choose(true);}).setNegativeButton("Cancelar",null).show();}
 void choose(boolean export){try{a.startActivityForResult(new Intent(export?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"Seeky_Backup_"+new java.text.SimpleDateFormat("yyyyMMdd-HHmm",Locale.ROOT).format(new Date())+".zip"),export?EXPORT:RESTORE);}catch(Exception e){PlusUi.error(a,e);}}
 void result(int request,int result,Intent data){if(request!=EXPORT&&request!=RESTORE||result!=Activity.RESULT_OK||data==null||data.getData()==null)return;BackupWork.enqueue(a,data.getData(),request==RESTORE,conversations,audio,data.getFlags());}
 void recoveries(){File root=new File(a.getFilesDir(),"workspace-recovery");File[] files=root.listFiles((d,n)->n.matches("before-[0-9]+(?:-[a-f0-9-]+)?\\.zip"));if(files==null||files.length==0){PlusUi.toast(a,"Ainda não há recuperações locais anteriores.");return;}Arrays.sort(files,(x,y)->Long.compare(y.lastModified(),x.lastModified()));List<File> choices=Arrays.asList(files);PagedPicker.show(a,"Antes das recuperações",(query,offset,limit)->{List<File> matching=new ArrayList<>();for(File f:choices){String date=new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.ROOT).format(new Date(f.lastModified()));if(query.isEmpty()||date.contains(query))matching.add(f);}List<PagedPicker.Entry> rows=new ArrayList<>();for(int i=offset;i<Math.min(matching.size(),offset+limit);i++){File f=matching.get(i);rows.add(new PagedPicker.Entry(f.getPath(),new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.ROOT).format(new Date(f.lastModified())),android.text.format.Formatter.formatShortFileSize(a,f.length())));}return new PagedPicker.Page(rows,matching.size());},e->BackupWork.local(a,new File(e.id)));}
 void close(){}
}
